public class Demo {
    public static void main(String[] args) throws InterruptedException {
        // Le Runnable : la tache a executer, ecrite sous forme de lambda.
        Runnable tache = () -> {
            System.out.println("Bonjour depuis un autre thread !");
        };

        // On cree un thread en lui confiant la tache.
        Thread t = new Thread(tache);

        // start() DEMARRE un nouveau thread qui executera run() en parallele.
        t.start();

        // join() attend que le thread t ait fini avant de continuer.
        t.join();
        System.out.println("Le thread principal reprend la main.");
    }
}

import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;

public class Demo {
    public static void main(String[] args) {
        // Un pool de 4 threads reutilises pour toutes les taches.
        ExecutorService pool = Executors.newFixedThreadPool(4);

        // On soumet 10 taches : le pool les distribue sur ses 4 threads.
        for (int i = 1; i <= 10; i++) {
            int numero = i; // variable effectivement finale, utilisable dans la lambda
            pool.submit(() -> {
                System.out.println("Tache " + numero + " sur le thread "
                        + Thread.currentThread().getName());
            });
        }

        // shutdown() : on refuse les nouvelles taches et on laisse finir les en cours.
        pool.shutdown();
    }
}

import java.util.concurrent.*;

public class Demo {
    public static void main(String[] args) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(2);

        // Un Callable<Integer> : la tache calcule et RENVOIE un entier.
        Callable<Integer> calcul = () -> {
            int total = 0;
            for (int i = 1; i <= 100; i++) total += i;
            return total; // call() renvoie une valeur, contrairement a run()
        };

        // submit rend tout de suite un Future : le "recu" du resultat a venir.
        Future<Integer> ticket = pool.submit(calcul);

        // On peut faire autre chose ici pendant que le calcul tourne...

        // get() recupere le resultat ; il ATTEND (bloque) si ce n'est pas encore pret.
        Integer resultat = ticket.get();
        System.out.println("Somme de 1 a 100 = " + resultat); // 5050

        pool.shutdown();
    }
}
